package NPB.SER;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Compares what a SER kernel prints with the "golden" values of the
 * official reference (src/test/resources/golden/, generated by
 * scripts/gen_golden.py): CG, EP and MG (the ones that add something beyond their
 * own verification), plus FT (checksums of each iteration), IS (digest
 * of the sorted array, exact comparison) and SP, BT and LU (RMS norms of the residual and of the error; LU also the surface integral).
 */
final class GoldenCheck {

	/**
	 * Relative tolerances, set from the measured differences. MG: 2 ulp; it measures 0
	 * (bit for bit) since psinv sums in the same order as Fortran; with 1e-13 that defect would go unnoticed.
	 */
	static final double CG_ZETA_RTOL = Double.parseDouble(System.getProperty("golden.cg.rtol", "1e-13"));
	/** CG ||r||: measures 0 (bit for bit) in S, W, A and B; it is the rounding floor, so it detects any change of order. */
	static final double CG_RNORM_RTOL = Double.parseDouble(System.getProperty("golden.cg.rnorm.rtol", "0"));
	/** EP: bit for bit in S, W, A and B (17 digits); 2 ulp of margin. */
	static final double EP_SUM_RTOL = Double.parseDouble(System.getProperty("golden.ep.rtol", "4.5e-16"));
	/**
	 * FT: 1e-15 (~4.5 ulp). With the real code up to 4.5e-16 is measured because Math.exp does not always give the same as
	 * glibc's exp in twiddle (1 ulp in ~0.1% of the points); with the glibc values in its place it is bit for bit.
	 */
	static final double FT_CHK_RTOL = Double.parseDouble(System.getProperty("golden.ft.rtol", "1e-15"));
	static final double MG_RNM2_RTOL = Double.parseDouble(System.getProperty("golden.mg.rtol", "4.5e-16"));
	/**
	 * SP: bit for bit in S, W, A and B (17 digits). The serial version has no reductions (the norm sums go in a fixed
	 * order), so 0 is required; the OMP and MPI versions of SP round differently (e.g. btuz/ac versus btuz*acinv)
	 * and differ by ~1e-12, so a translation taken from MPI would not pass.
	 */
	static final double SP_NORM_RTOL = Double.parseDouble(System.getProperty("golden.sp.rtol", "0"));
	/**
	 * BT: bit for bit in S, W, A and B (17 digits), like SP: no reductions, fixed order of the sums. The norms of the
	 * OMP and MPI versions may differ in the last digit, so SER is compared only with OMP.
	 */
	static final double BT_NORM_RTOL = Double.parseDouble(System.getProperty("golden.bt.rtol", "0"));
	/** LU: bit for bit in S, W, A and B (17 digits), norms and surface integral; no reductions in the serial version. */
	static final double LU_NORM_RTOL = Double.parseDouble(System.getProperty("golden.lu.rtol", "0"));

	private GoldenCheck() {
	}

	static Properties load(String kernel, char cls) throws IOException {
		String res = "/golden/" + kernel.toLowerCase() + "." + cls + ".properties";
		try (InputStream in = GoldenCheck.class.getResourceAsStream(res)) {
			if (in == null)
				return null;
			Properties p = new Properties();
			p.load(in);
			return p;
		}
	}

	/** Checks a kernel's output; returns false if there is no fixture. */
	static boolean check(String kernel, char cls, String out) throws IOException {
		Properties g = load(kernel, cls);
		if (g == null)
			return false;
		String id = kernel + " class " + cls;
		switch (kernel) {
		case "CG":
			checkCG(id, g, out);
			break;
		case "EP":
			checkEP(id, g, out);
			break;
		case "MG":
			checkMG(id, g, out);
			break;
		case "FT":
			checkFT(id, g, out);
			break;
		case "IS":
			checkIS(id, g, out);
			break;
		case "SP":
			checkSP(id, g, out, SP_NORM_RTOL);
			break;
		case "BT":
			checkSP(id, g, out, BT_NORM_RTOL);
			break;
		case "LU":
			checkSP(id, g, out, LU_NORM_RTOL);
			checkLUSurfaceIntegral(id, g, out);
			break;
		default:
			return false;
		}
		return true;
	}

	private static void checkCG(String id, Properties g, String out) {
		int niter = Integer.parseInt(g.getProperty("niter"));
		Matcher m = Pattern.compile("^\\s+(\\d+)\\s+(\\S+)\\s+(\\S+)\\s*$", Pattern.MULTILINE).matcher(out);
		List<Double> zeta = new ArrayList<>();
		List<Double> rnorm = new ArrayList<>();
		int expected = 1;
		while (m.find()) {
			assertEquals(expected++, Integer.parseInt(m.group(1)), id + ": non-consecutive iterations");
			rnorm.add(Double.parseDouble(m.group(2)));
			zeta.add(Double.parseDouble(m.group(3)));
		}
		assertEquals(niter, zeta.size(), id + ": number of printed iterations");
		double max = 0;
		for (int i = 1; i <= niter; i++)
			max = Math.max(max, compare(id + " zeta[" + i + "]", Double.parseDouble(g.getProperty("zeta." + i)),
					zeta.get(i - 1), CG_ZETA_RTOL));
		report(id, "zeta (all iterations)", max);
		double maxR = 0;
		for (int i = 1; i <= niter; i++)
			maxR = Math.max(maxR, compare(id + " rnorm[" + i + "]", Double.parseDouble(g.getProperty("rnorm." + i)),
					rnorm.get(i - 1), CG_RNORM_RTOL));
		report(id, "rnorm (all iterations)", maxR);
	}

	private static void checkEP(String id, Properties g, String out) {
		double gcJava = Double.parseDouble(find(id, "No\\. Gaussian Pairs =\\s*(\\S+)", out));
		assertEquals(Double.parseDouble(g.getProperty("gc")), gcJava, id + ": gc (integer, exact)");
		Matcher m = Pattern.compile("Sums =\\s*(\\S+)\\s+(\\S+)").matcher(out);
		assertTrue(m.find(), id + ": Sums line not found");
		double max = Math.max(
				compare(id + " sx", Double.parseDouble(g.getProperty("sx")), Double.parseDouble(m.group(1)), EP_SUM_RTOL),
				compare(id + " sy", Double.parseDouble(g.getProperty("sy")), Double.parseDouble(m.group(2)), EP_SUM_RTOL));
		report(id, "sx, sy", max);
		String tail = out.substring(out.indexOf("Counts:"));
		Matcher c = Pattern.compile("^\\s*(\\d+)\\s+(\\d+)\\.\\s*$", Pattern.MULTILINE).matcher(tail);
		int n = 0;
		while (c.find() && n < 10) {
			assertEquals(n, Integer.parseInt(c.group(1)), id + ": counters out of order");
			assertEquals(Long.parseLong(g.getProperty("q." + n)), Long.parseLong(c.group(2)),
					id + ": counter q" + n + " (integer, exact)");
			n++;
		}
		assertEquals(10, n, id + ": missing counters");
	}

	private static void checkIS(String id, Properties g, String out) {
		Matcher m = Pattern.compile("Sorted keys digest =\\s*(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)").matcher(out);
		assertTrue(m.find(), id + ": sorted array digest not found");
		String[] key = { "n", "s1", "s2", "s3" };
		for (int k = 0; k < 4; k++)
			assertEquals(Long.parseUnsignedLong(g.getProperty("digest." + key[k])), Long.parseUnsignedLong(m.group(k + 1)),
					id + ": digest " + key[k] + " (integer, exact)");
	}

	private static void checkFT(String id, Properties g, String out) {
		int niter = Integer.parseInt(g.getProperty("niter"));
		Matcher m = Pattern.compile("T =\\s*(\\d+)\\s+Checksum =\\s*\\(([^,]+),\\s*([^)]+)\\)").matcher(out);
		int n = 0;
		double max = 0;
		while (m.find()) {
			int it = Integer.parseInt(m.group(1));
			assertEquals(++n, it, id + ": non-consecutive iterations");
			max = Math.max(max, compare(id + " chk[" + it + "].re", Double.parseDouble(g.getProperty("chk." + it + ".re")),
					Double.parseDouble(m.group(2)), FT_CHK_RTOL));
			max = Math.max(max, compare(id + " chk[" + it + "].im", Double.parseDouble(g.getProperty("chk." + it + ".im")),
					Double.parseDouble(m.group(3)), FT_CHK_RTOL));
		}
		assertEquals(niter, n, id + ": number of printed checksums");
		report(id, "checksums (all iterations)", max);
	}

	/** LU surface integral (xci): the line following "Comparison of surface integral". */
	private static void checkLUSurfaceIntegral(String id, Properties g, String out) {
		Matcher m = Pattern.compile("Comparison of surface integral\\s*\\n\\s*(\\S+)\\s+(\\S+)\\s+(\\S+)").matcher(out);
		assertTrue(m.find(), id + ": surface integral missing");
		report(id, "xci", compare(id + " xci", Double.parseDouble(g.getProperty("xci")), Double.parseDouble(m.group(1)),
				LU_NORM_RTOL));
	}

	/** RMS norms (xcr and xce) of SP, BT and LU: same output format. */
	private static void checkSP(String id, Properties g, String out, double rtol) {
		String[][] sections = { { "xcr", "Comparison of RMS-norms of residual" },
				{ "xce", "Comparison of RMS-norms of solution error" } };
		double max = 0;
		for (String[] s : sections) {
			int at = out.indexOf(s[1]);
			assertTrue(at >= 0, id + ": missing section '" + s[1] + "'");
			Matcher m = Pattern.compile("^\\s*(\\d)\\s+(\\S+)\\s+(\\S+)\\s+(\\S+)\\s*$", Pattern.MULTILINE)
					.matcher(out.substring(at));
			for (int c = 1; c <= 5; c++) {
				assertTrue(m.find(), id + ": missing components of " + s[0]);
				assertEquals(c, Integer.parseInt(m.group(1)), id + ": components out of order in " + s[0]);
				max = Math.max(max, compare(id + " " + s[0] + "[" + c + "]", Double.parseDouble(g.getProperty(s[0] + "." + c)),
						Double.parseDouble(m.group(2)), rtol));
			}
		}
		report(id, "xcr, xce (10 normas)", max);
	}

	private static void checkMG(String id, Properties g, String out) {
		double v = Double.parseDouble(find(id, "L2 Norm is\\s+(\\S+)", out));
		report(id, "rnm2", compare(id + " rnm2", Double.parseDouble(g.getProperty("rnm2")), v, MG_RNM2_RTOL));
	}

	private static String find(String id, String regex, String out) {
		Matcher m = Pattern.compile(regex).matcher(out);
		if (!m.find())
			fail(id + ": /" + regex + "/ not found in the output");
		return m.group(1);
	}

	/** Fails if the relative difference exceeds rtol (or is NaN); returns the difference. */
	private static double compare(String what, double expected, double actual, double rtol) {
		double rel = Math.abs(actual - expected) / Math.abs(expected);
		assertTrue(rel <= rtol, what + ": official=" + expected + " Java=" + actual + " relDiff=" + rel
				+ " > " + rtol); // `!(rel <= rtol)` also fails on NaN
		return rel;
	}

	private static void report(String id, String what, double maxRel) {
		System.err.printf("GOLDEN %s %s maxRelDiff=%.3e%n", id, what, maxRel);
	}
}
